import { existsSync } from 'node:fs';
import { join } from 'node:path';
export function guidePath(guideId: string) {
  return `/guides/${guideId}/`;
}

// PDFs are generated by `npm run pdfs` into public/downloads/ and committed.
export function pdfPath(guideId: string) {
  return `/downloads/perseverant-digital-${guideId}-guide.pdf`;
}

export function pdfExists(guideId: string) {
  return existsSync(join(process.cwd(), 'public', pdfPath(guideId)));
}

// Each version keeps only the Sources it cites. A source stays when one of its
// names appears in the text above the Sources heading.
const SOURCE_ALIASES: [RegExp, string[]][] = [
  [/[Ss]olar/, ['solar', 'Solar']],
  [/CAN-SPAM/, ['CAN-SPAM']],
  [/Federal Trade Commission|FTC/, ['FTC', 'Federal Trade Commission']],
  [/Health and Human Services|HHS/, ['HHS', 'HIPAA']],
  [/American Society of Plastic Surgeons/, ['ASPS', 'American Society of Plastic Surgeons']],
  [/Joint Center for Housing Studies/, ['Joint Center', 'JCHS']],
  [/Staffing Industry Analysts/, ['Staffing Industry Analysts', 'SIA']],
  [/^NIC|NIC MAP/, ['NIC MAP', 'NIC']],
  [/Florida Bar/, ['Florida']],
  [/Texas Center for Legal Ethics/, ['Texas requires', 'Advertising Review Committee', 'Texas']],
  [/Texas Legislature|HB 2733/, ['HB 2733', 'barratry']],
  [/iLawyer/, ['iLawyer']],
  [/Hinshaw/, ['24-1']],
  [/Meta for Developers|^Meta\b/, ['Special Ad Categor', 'housing category', 'employment category', 'credit category']],
  [/National Association of Home Builders|NAHB/, ['Housing for Older Persons', 'NAHB', '55+']],
  [/Google Business Profile Help/, ['relevance, distance', 'relevance', 'pay for a better']],
  [/^(Google|Alphabet)\b(?! Business)/, ['AI Mode', 'Pichai', 'sender', 'Gmail']],
  [/Home Health Care News|Activated Insights/, ['turnover', 'Activated Insights', 'Home Care Pulse']],
  [/Senior Housing News/, ['Senior Housing News', 'Bild', 'move-ins']],
  [/ASIS/, ['ASIS']],
  [/Clio/, ['Clio']],
  [/Harvard Business Review/, ['Harvard Business Review', 'HBR']],
  [/Kelley Drye/, ['Kelley Drye', 'one-to-one', 'Eleventh Circuit', 'prior express written consent']],
  [/Burr/, ['Burr', 'revoke-all', 'January 31, 2027', 'any reasonable means']],
];

function sourceNames(li: string) {
  const text = li.replace(/<[^>]+>/g, '').replace(/&#x27;|&#39;/g, "'").trim();
  for (const [re, names] of SOURCE_ALIASES) if (re.test(text)) return names;
  const first = text.split(/[,(“"]/)[0].trim();
  return [first];
}

export function citedSourcesOnly(html: string) {
  const m = html.match(/(<h2[^>]*>Sources<\/h2>\s*<ul>)([\s\S]*?)(<\/ul>)/);
  if (!m || m.index === undefined) return html;
  const body = html.slice(0, m.index).replace(/<[^>]+>/g, ' ');
  const kept = (m[2].match(/<li>[\s\S]*?<\/li>/g) ?? []).filter((li) =>
    sourceNames(li).some((n) => n && body.includes(n)),
  );
  return html.slice(0, m.index) + m[1] + '\n' + kept.join('\n') + '\n' + m[3] + html.slice(m.index + m[0].length);
}
